/* -------------------------------------
            ASSETS
------------------------------------- */
/* --- FONTS --- */
/* Lora */
@font-face {
  font-family: "Lora";
  src: url("data:font/woff2;charset=utf-8;base64,") format("woff2");
  font-weight: unset;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Lora";
  src: url("data:font/woff2;charset=utf-8;base64,") format("woff2");
  font-weight: unset;
  font-style: italic;
  font-display: swap;
}
/* Fraunces */
@font-face {
  font-family: "Fraunces";
  src: url("data:font/woff2;charset=utf-8;base64,") format("woff2");
  font-weight: unset;
  font-style: normal;
  font-display: swap;
  font-optical-sizing: auto;
  font-variation-settings: "SOFT" 100, "WONK" 100;
}
@font-face {
  font-family: "Fraunces";
  src: url("data:font/woff2;charset=utf-8;base64,") format("woff2");
  font-weight: unset;
  font-style: italic;
  font-display: swap;
  font-optical-sizing: auto;
  font-variation-settings: "SOFT" 100, "WONK" 100;
}
/* Manrope */
@font-face {
  font-family: "Manrope";
  src: url("data:font/ttf;charset=utf-8;base64,") format("truetype");
  font-weight: unset;
  font-style: normal;
  font-display: swap;
}
/* Victor Mono */
@font-face {
  font-family: "Victor Mono";
  src: url("data:font/ttf;charset=utf-8;base64,") format("truetype");
  font-weight: unset;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Victor Mono";
  src: url("data:font/ttf;charset=utf-8;base64,") format("truetype");
  font-weight: unset;
  font-style: italic;
  font-display: swap;
}
/* Lexend */
@font-face {
  font-family: "Lexend";
  src: url("data:font/ttf;charset=utf-8;base64,") format("truetype");
  font-weight: unset;
  font-style: normal;
  font-display: swap;
}
/* -------------------------------------
            VARIABLES
------------------------------------- */
:root {
  --vr-font-header: "Fraunces";
  --vr-header-symbol: "#"; /* § */
  --vr-header-symbol-offset: 0.3em;
  --vr-h1-weight: 800;
  --vr-h2-weight: 800;
  --vr-h3-weight: 600;
  --vr-h4-weight: 600;
  --vr-h5-weight: 500;
  --vr-h6-weight: 500;
  --vr-horizontal-rule-symbol: "§"; /* ¶ */
  --vr-border-radius: 8px;
}

/* -------------------------------------
            COLOUR SCHEMES
------------------------------------- */
.theme-dark {
  /* Text Colours */
  --text-normal: #f7edeb;
  --text-muted: #f0d3c9;
  --text-faint: #665957;
  --text-on-accent: #9e9892;
  --text-on-accent-inverted: #282727;
  /* Semantic Colours */
  --background-primary: #282727;
  --background-primary-alt: #343231;
  --background-secondary: #2e2d2d;
  --background-secondary-alt: #282727;
  --background-modifier-border: #4d4238;
  --background-modifier-error: #000000;
  --background-modifier-error-rgb: #000000;
  --background-modifier-error-hover: #000000;
  --background-modifier-success: #c2d36880;
  --background-modifier-message: #9e989280;
  --background-modifier-form-field: #343231;
}

.theme-light {
  /* Text Colours */
  --text-normal: #33271a;
  --text-muted: #474032;
  --text-faint: #9e9892;
  --text-on-accent: #f7edeb;
  --text-on-accent-inverted: #33271a;
  /* Semantic Colours */
  --background-primary: #f5f4f2;
  --background-primary-alt: #f0eeeb;
  --background-secondary: #edeae4;
  --background-secondary-alt: #e3ded5;
  --background-modifier-border: #ded6cc;
  --background-modifier-error: #000000;
  --background-modifier-error-rgb: rgb(0,0,0);
  --background-modifier-error-hover: #000000;
  --background-modifier-success: #c2d36880;
  --background-modifier-message: #9e989280;
  --background-modifier-form-field: #e3ded5;
}

.vr-dark-oled.theme-dark {
  /* Text Colours */
  --text-normal: #ffffff;
  --text-muted: #f0d3c9;
  --text-faint: #665957;
  --text-on-accent: #ffffff;
  --text-on-accent-inverted: #000000;
  /* Semantic Colours */
  --background-primary: #000000;
  --background-primary-alt: #000000;
  --background-secondary: #000000;
  --background-secondary-alt: #000000;
  --background-modifier-border: #1a1a1a;
  --background-modifier-error: #000000;
  --background-modifier-error-rgb: #000000;
  --background-modifier-error-hover: #000000;
  --background-modifier-success: #c2d36880;
  --background-modifier-message: #9e989280;
  --background-modifier-form-field: #000000;
}

.vr-dark-nord.theme-dark {
  /* Text Colours */
  --text-normal: #eceff4;
  --text-muted: #e5e9f0;
  --text-faint: #d8dee9;
  --text-on-accent: #eceff4;
  --text-on-accent-inverted: #9e9892;
  /* Semantic Colours */
  --background-primary: #2e3440;
  --background-primary-alt: #3b4252;
  --background-secondary: #434c5e;
  --background-secondary-alt: #4c566a;
  --background-modifier-border: #4c566a;
  --background-modifier-error: #000000;
  --background-modifier-error-rgb: #000000;
  --background-modifier-error-hover: #000000;
  --background-modifier-success: #c2d36880;
  --background-modifier-message: #9e989280;
  --background-modifier-form-field: #2e3440;
}

/* -------------------------------------
            OBSIDIAN
------------------------------------- */
/* Headers */
.el-h1 h1,
.el-h2 h2,
.el-h3 h3,
.el-h4 h4,
.el-h5 h5,
.el-h6 h6 {
  font-family: var(--vr-font-header);
}

.el-h1 h1 {
  font-weight: var(--vr-h1-weight);
}

.el-h2 h2 {
  font-weight: var(--vr-h2-weight);
}

.el-h3 h3 {
  font-weight: var(--vr-h3-weight);
}

.el-h4 h4 {
  font-weight: var(--vr-h4-weight);
}

.el-h5 h5 {
  font-weight: var(--vr-h5-weight);
}

.el-h6 h6 {
  font-weight: var(--vr-h6-weight);
}

/* --- TABLES --- */
/* Normal Tables */
.markdown-rendered th,
.cm-html-embed thead tr > th:nth-child(2n+2),
.markdown-rendered thead tr > th:nth-child(2n+2) {
  border-color: var(--background-modifier-border);
  background-color: var(--background-primary-alt);
}

.markdown-rendered td {
  border-color: var(--background-modifier-border);
  background-color: var(--background-primary);
}

/* Dataview Tables */
.table-view-table {
  border-collapse: collapse;
  border: 1px solid var(--color-base-40);
}
.table-view-table .table-view-th {
  border-width: 0px;
  border-bottom: 1px solid var(--color-base-40);
  border-right: 1px solid var(--color-base-40);
}
.table-view-table .table-view-tbody {
  border-width: 0px;
}
.table-view-table .table-view-tbody tr {
  border-bottom: 1px solid var(--color-base-40);
}
.table-view-table .table-view-tbody td {
  border-right: 1px solid var(--color-base-40);
}

/* --- BLOCKQUOTES --- */
:not(.is-phone) .markdown-rendered blockquote {
  max-width: 66%;
}

.markdown-rendered blockquote {
  background-color: color-mix(in oklch, var(--color-accent) 10%, transparent);
  border: 1px solid var(--color-accent);
  border-left-width: 6px;
  margin-left: auto;
  margin-right: auto;
  padding-top: 0.5em;
  padding-bottom: 0.5em;
  padding-left: 1em;
  padding-right: 1em;
  z-index: 0;
  position: relative;
  overflow: hidden;
}
.markdown-rendered blockquote::before {
  content: ">";
  display: inline;
  font-size: 3em;
  font-weight: 400;
  line-height: 3em;
  color: color-mix(in oklch, var(--color-accent) 50%, transparent);
  position: absolute;
  bottom: 0.75em;
  right: 1%;
  max-width: 1em;
  max-height: 1em;
  text-align: right;
  z-index: -1;
}

/* --- LINKS --- */
.markdown-rendered .internal-link, .markdown-rendered .external-link, .markdown-rendered .tag {
  text-decoration: none;
}
.markdown-rendered .external-link {
  color: var(--color-blue);
}
.markdown-rendered cite {
  text-decoration: none;
  font-style: normal;
  font-weight: 600;
}
.markdown-rendered {
  /* Stop footnotes affecting line height */
}
.markdown-rendered .footnote-ref {
  vertical-align: top;
  top: -0.3em;
}

/* --- CALLOUTS --- */
.callout {
  border: 1px solid var(--callout-color);
  border-radius: var(--vr-border-radius);
}
.callout .callout-title {
  flex-direction: row;
  justify-content: space-between;
  border-top-left-radius: var(--vr-border-radius);
  border-top-right-radius: var(--vr-border-radius);
  gap: 5px;
}
.callout .callout-title .callout-fold {
  order: 1;
  padding-top: 0;
  color: var(--callout-color);
}
.callout .callout-title .callout-title-inner {
  order: 2;
  color: var(--callout-color);
}
.callout .callout-title .callout-icon {
  order: 3;
  padding-right: 0.25em;
}
.callout .callout-title svg {
  width: 1em;
  height: 1em;
}
.callout .is-collapsed .callout-title {
  border-radius: var(--vr-border-radius);
}
.callout .is-collapsed .callout-content {
  opacity: 0;
}
.callout[data-callout=metadata] {
  --callout-color: var(--color-accent);
  --callout-icon: coffee;
}
.callout[data-callout=pro], .callout[data-callout=do] {
  --callout-color: rgb(156, 219, 67);
  --callout-icon: thumbs-up;
}
.callout[data-callout=con], .callout[data-callout="don't"] {
  --callout-color: rgb(223, 62, 35);
  --callout-icon: thumbs-down;
}
.callout[data-callout=spell] {
  --callout-color: rgb(140, 49, 123);
  --callout-icon: wand;
}
.callout[data-callout=weapon] {
  --callout-color: rgb(115, 107, 159);
  --callout-icon: axe;
}
.callout[data-callout=encounter] {
  --callout-icon: shield;
}

.callout > .is-collapsed .callout-title {
  border: 0px;
}

.callout-content {
  margin-bottom: -0.5em;
}

/* --- HORIZONTAL RULES --- */
.markdown-rendered hr::after {
  content: var(--vr-horizontal-rule-symbol);
  display: inline-block;
  position: absolute;
  left: 50%;
  transform-origin: 50% 50%;
  transform: translate(-50%, -55%) rotate(0deg);
  background-color: var(--background-primary);
  color: var(--color-accent);
  padding: 0.25em 0.5em;
}

/* --- CODEBLOCKS --- */
.markdown-rendered code {
  color: var(--color-red);
  background-color: var(--background-secondary);
}

/* --- SIDEBAR --- */
.workspace .mod-sidedock.mod-left-split .workspace-tab-header-container {
  border-right: 1px solid var(--background-modifier-border);
}

.workspace .mod-sidedock.mod-right-split .workspace-tab-header-container {
  border-left: 1px solid var(--background-modifier-border);
}

.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space {
  --sidebar-tab-text-display: inline-block;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header {
  background-color: inherit;
  color: var(--text-faint);
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header .workspace-tab-header-inner-icon {
  color: var(--text-faint);
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header:not(.is-active):hover {
  border: none;
  box-shadow: none;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner-icon {
  color: var(--text-muted);
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner {
  background-color: inherit;
  color: var(--text-muted);
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-inner {
  padding: var(--size-2-3) var(--size-2-3);
  justify-content: left;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-inner-title {
  padding-left: 0.6em;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-container {
  max-height: unset;
  height: fit-content;
  padding-bottom: 0;
  background-color: transparent;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-container .workspace-tab-header.is-active {
  background-color: inherit;
  color: var(--text-normal);
  font-weight: bold;
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-container .workspace-tab-header.is-active .workspace-tab-header-inner-icon {
  color: var(--text-normal);
}
.vr-nav-labels-left .workspace .mod-sidedock.mod-left-split .mod-top-left-space .workspace-tab-header-container-inner {
  flex-direction: column;
  width: stretch;
  gap: 0;
  padding-left: 0;
  max-height: unset;
}

.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space {
  --sidebar-tab-text-display: inline-block;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header {
  background-color: inherit;
  color: var(--text-faint);
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header .workspace-tab-header-inner-icon {
  color: var(--text-faint);
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header:not(.is-active):hover {
  border: none;
  box-shadow: none;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner-icon {
  color: var(--text-muted);
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header:not(.is-active):hover .workspace-tab-header-inner {
  background-color: inherit;
  color: var(--text-muted);
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-inner {
  padding: var(--size-2-3) var(--size-2-3);
  justify-content: left;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-inner-title {
  padding-left: 0.6em;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-container {
  max-height: unset;
  height: fit-content;
  padding-bottom: 0;
  background-color: transparent;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-container .workspace-tab-header.is-active {
  background-color: inherit;
  color: var(--text-normal);
  font-weight: bold;
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-container .workspace-tab-header.is-active .workspace-tab-header-inner-icon {
  color: var(--text-normal);
}
.vr-nav-labels-right .workspace .mod-sidedock.mod-right-split .mod-top-right-space .workspace-tab-header-container-inner {
  flex-direction: column;
  width: stretch;
  gap: 0;
  padding-left: 0;
  max-height: unset;
}

body:not(.is-phone) .nav-buttons-container {
  justify-content: right;
}

.tree-item-self.nav-folder-title {
  font-style: italic;
}

/* --- STATUSBAR --- */
.status-bar {
  position: absolute;
  right: 16px;
  bottom: 16px;
  background-color: var(--background-primary);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--vr-border-radius);
  justify-content: flex-end;
  align-items: center;
  max-height: unset;
  height: 3em;
  padding: 0px 2px;
}

.status-bar-item:not(:first-child):not(:nth-child(2)):not(.separator)::before {
  content: "∙";
  color: var(--text-faint);
  font-weight: 800;
  position: relative;
  right: 0.5em;
}

/* --- INTERFACE --- */
/* Interface Colouring */
.titlebar,
.status-bar,
.side-dock-ribbon,
.workspace-tabs,
.workspace-tab-header-container,
.workspace-tab-header-container .is-before-active,
.workspace-tab-header-container .is-active,
.workspace-tab-header-container .is-after-active,
.nav-header,
.nav-files-container,
.workspace-split .view-content,
.view-header,
.view-header-title-container,
.view-header-title-container::after,
.view-header-title {
  background: var(--background-primary);
}

/* -------------------------------------
            FEATURES
------------------------------------- */
/* Preview Mode */
.el-h1 h1,
.el-h2 h2,
.el-h3 h3,
.el-h4 h4,
.el-h5 h5,
.el-h6 h6 {
  border-radius: var(--vr-border-radius);
  padding-left: 2%;
  padding-right: 2%;
  position: relative;
  overflow: hidden; /* This maaaaay be a little busted */
  background-color: color-mix(in oklch, var(--color-accent) 20%, transparent);
  color: var(--color-accent);
  z-index: 0;
}
.el-h1 h1::before,
.el-h2 h2::before,
.el-h3 h3::before,
.el-h4 h4::before,
.el-h5 h5::before,
.el-h6 h6::before {
  content: var(--vr-header-symbol);
  font-size: 2em;
  font-weight: 800;
  line-height: 2em;
  color: var(--background-primary);
  position: absolute;
  bottom: var(--vr-header-symbol-offset);
  right: 1%;
  max-width: 1em;
  max-height: 1em;
  text-align: right;
  z-index: -1;
}

/* --- ASIDE STYLING --- */
aside {
  display: block;
  float: right;
  width: 50%;
  border: 1px solid var(--background-modifier-border);
  border-left-width: 6px;
  background: var(--background-secondary);
  padding: 10px 20px;
  margin: 5px 0px 5px 10px;
}

/* --- ROUNDNESS --- */
blockquote,
.css-inline-code,
img[src]:not(.banner-image),
aside,
button,
.mod-empty,
pre[class*=language-],
.modal,
.prompt,
input {
  border-radius: var(--vr-border-radius);
}

.cm-s-obsidian div.HyperMD-codeblock-begin-bg {
  border-top-left-radius: var(--vr-border-radius);
  border-top-right-radius: var(--vr-border-radius);
}

.cm-s-obsidian div.HyperMD-codeblock-end-bg {
  border-bottom-left-radius: var(--vr-border-radius);
  border-bottom-right-radius: var(--vr-border-radius);
}

/* Rounded Tables
NOTE: 
    This is a really, REALLY weird bodge.
You can't apply a border radius to a border
that's been collapsed, so I got rid of the
spacing and it seemed to work.

    If you are much more experienced with
CSS than myself, feel free to try and fix
this thing up.
*/
.markdown-rendered table:not(.table-view-table) {
  border-collapse: separate;
  border-spacing: 0;
}
.markdown-rendered table:not(.table-view-table) tr:first-child th:first-child {
  border-top-left-radius: var(--vr-border-radius);
}
.markdown-rendered table:not(.table-view-table) tr:first-child th:last-child {
  border-top-right-radius: var(--vr-border-radius);
}
.markdown-rendered table:not(.table-view-table) tr:last-child td:first-child {
  border-bottom-left-radius: var(--vr-border-radius);
}
.markdown-rendered table:not(.table-view-table) tr:last-child td:last-child {
  border-bottom-right-radius: var(--vr-border-radius);
}

/* --- CLEAN EMBED --- */
.markdown-embed {
  margin: 0px;
  padding: 0px;
  border: none;
}
.markdown-embed-content > .markdown-preview-view {
  max-height: unset;
  padding: 0px;
}
.markdown-embed-title, .markdown-embed-link, .markdown-embed-page::-webkit-scrollbar, .markdown-embed .show-indentation-guide::-webkit-scrollbar {
  display: none;
}

.inline-embed > .markdown-embed-content > .markdown-preview-view {
  padding: 0;
}

/* Shrink space taken by "not created" messages */
.file-embed.mod-empty {
  padding: 5px 10px;
  margin: 0px;
}

/* GPLv3 license
